  /**
   * Evaluates current run assertions against baseline assertions and classifies the comparative outcome
   * into one of 12 distinct deterministic states.
   */
  static compareRuns(
    manifest: RunManifest,
    currentAssertions: Record<string, boolean>,
    baseline: BaselineSpecification,
    baselineAssertions: Record<string, boolean>,
    isRepeatReproduction = false,
    options?: { isPriorRegressionCandidate?: boolean; isKnownFlaky?: boolean }
  ): BaselineComparisonResult {
    // 1. Check basic execution statuses and failure types
    if (manifest.status === "CANCELLED") {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "CANCELLED",
        divergences: [],
        confidence: 1.0,
        explanation: "Run was cancelled by operator before completion.",
      };
    }

    if (manifest.status === "INTERRUPTED" || manifest.status === "INCONCLUSIVE") {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "INCONCLUSIVE",
        divergences: [],
        confidence: 0.0,
        explanation:
          manifest.terminationReason ??
          "Run was inconclusive or interrupted before assertions could be finalized.",
      };
    }

    if (manifest.status === "NOT_EXECUTED") {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "NOT_EXECUTED",
        divergences: [],
        confidence: 1.0,
        explanation: "Run was scheduled or created but not executed.",
      };
    }

    if (
      manifest.status === "INFRASTRUCTURE_FAILURE" ||
      manifest.terminationReason?.toLowerCase().includes("infrastructure")
    ) {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "INFRASTRUCTURE_FAILURE",
        divergences: [],
        confidence: 1.0,
        explanation:
          manifest.terminationReason ??
          "Run failed due to infrastructure or environment failure.",
      };
    }

    if (
      manifest.status === "EVALUATOR_DEFECT" ||
      manifest.terminationReason?.toLowerCase().includes("evaluator defect")
    ) {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "EVALUATOR_DEFECT",
        divergences: [],
        confidence: 1.0,
        explanation:
          manifest.terminationReason ??
          "Run failed due to defect in assertion evaluation harness or specification.",
      };
    }

    // Only a run that reached a terminal executed state can be classified. RUNNING and any status this code does not
    // know are not evidence of anything.
    if (manifest.status !== "COMPLETED" && manifest.status !== "FAILED") {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "INCONCLUSIVE",
        divergences: [],
        confidence: 0.0,
        explanation: `Run status '${String(manifest.status)}' is not a finished execution; nothing to compare.`,
      };
    }

    // 2. Check baseline comparability
    const comp = this.checkComparability(manifest, baseline);
    if (!comp.eligible) {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        incomparabilityReasons: comp.reasons,
        outcome: "INCOMPARABLE",
        divergences: [],
        confidence: 0.0,
        explanation: `Incomparable configurations: ${comp.reasons.join("; ")}`,
      };
    }

    // 3. Compare assertions
    const allAssertionIds = Array.from(
      new Set([...Object.keys(currentAssertions), ...Object.keys(baselineAssertions)])
    );

    if (allAssertionIds.length === 0) {
      return {
        baselineId: baseline.baselineId,
        currentRunId: manifest.runId,
        isEligibleForComparison: false,
        outcome: "INCONCLUSIVE",
        divergences: [],
        confidence: 0.0,
        explanation: "Neither the run nor the baseline recorded any assertion; an empty comparison proves nothing.",
      };
    }

    const divergences: BaselineComparisonResult["divergences"] = [];
    let hasRegression = false;
    let hasImprovement = false;
    let allCurrentPassed = true;
    let allBaselinePassed = true;

    for (const id of allAssertionIds) {
      const hasCur = Object.prototype.hasOwnProperty.call(currentAssertions, id);
      const hasBase = Object.prototype.hasOwnProperty.call(baselineAssertions, id);

      // New assertion in current run not present in baseline: do not treat as improvement over baseline
      if (!hasBase) {
        if (!currentAssertions[id]) {
          allCurrentPassed = false;
        }
        continue;
      }

      // Assertion present in baseline but omitted from current run: regression in coverage/execution
      if (!hasCur) {
        allCurrentPassed = false;
        hasRegression = true;
        divergences.push({
          assertionId: id,
          baselineStatus: baselineAssertions[id] ? "PASS" : "FAIL",
          currentStatus: "FAIL",
          details: `Assertion '${id}' was verified in baseline but omitted from current run.`,
        });
        continue;
      }
  }

  /**
   * Executes a versioned evaluation definition against the target environment,
   * recording tamper-evident evidence and performing baseline comparison if requested.
   */
  static async runEvaluation(
    definition: EvaluationDefinition,
    options: EvaluationRunnerOptions,
    assertionExecutor?: (id: string, def: EvaluationDefinition) => Promise<boolean>
  ): Promise<EvaluationExecutionResult> {
    // Validate structural schema of the evaluation definition first
    validateEvaluationDefinition(definition);

    const gitInfo = CeriEvaluationRunner.getGitProvenance();
    const runId = `run-${definition.id}-${Date.now()}`;
    const startedAt = new Date().toISOString();

    const manifest: RunManifest = {
      runId,
      evaluationId: definition.id,
      evaluationVersion: definition.version,
      sourceCommit: options.baseCommit ?? gitInfo.commit,
      dirtyWorktree: options.dirtyWorktree ?? gitInfo.isDirty,
      model: options.model,
      routingConfig: {
        gatewayUrl: options.gatewayUrl,
        specialistRouting: options.specialistRouting ?? false,
      },
      agentProfileVersion: "1.1.2",
      harnessVersion: getBuildIdentity().version,
    // 3. Finalize run with tamper-proof integrity hash
    let finalStatus: RunStatus;
    let terminationReason: string;

    if (definition.deterministicAssertions.length === 0) {
      // An evaluation without assertions is inconclusive
      finalStatus = "INCONCLUSIVE";
      terminationReason = "Evaluation definition contains zero deterministic assertions to verify";
    } else if (!assertionExecutor) {
      finalStatus = "NOT_EXECUTED";
      terminationReason = "No assertion executor was supplied; no assertion was executed";
    } else {
      const allPassed = Object.values(assertionResults).every(Boolean);
      finalStatus = allPassed ? "COMPLETED" : "FAILED";
      terminationReason = allPassed
        ? "All assertions verified"
        : "One or more deterministic assertions failed";
    }

    manifest.status = finalStatus;
    manifest.completedAt = new Date().toISOString();
    manifest.durationMs = Date.now() - new Date(manifest.startedAt).getTime();
    manifest.terminationReason = terminationReason;

    const { integrityHash } = options.evidenceStore.finalizeRun(
      finalStatus,
      terminationReason
    );

    // 4. Perform baseline comparison if baseline specification is present
    let comparison: BaselineComparisonResult | undefined;
    if (options.baseline) {
      const loadedBaselineAssertions =
        options.baselineAssertions ??
        options.baseline.assertions ??
        options.evidenceStore.loadAssertions(
          options.baseline.evaluationId,
          options.baseline.baselineId
        );

      if (!loadedBaselineAssertions) {
        comparison = {
          baselineId: options.baseline.baselineId,
          currentRunId: manifest.runId,
          isEligibleForComparison: false,
          incomparabilityReasons: [
            `Baseline assertion records not found for baseline ID '${options.baseline.baselineId}'`,
          ],
          outcome: "INCOMPARABLE",
          divergences: [],
          confidence: 0.0,
          explanation:
            "Missing baseline assertion evidence: cannot verify comparative behavior without baseline assertions.",
        };
      } else {
        comparison = CeriBaselineComparator.compareRuns(
          manifest,
          assertionResults,
          options.baseline,
          loadedBaselineAssertions,
          options.isRepeatReproduction ?? false
        );
      }
    }

    return {
      manifest,
      assertions: assertionResults,
      integrityHash,
      comparison,
    };
  }
}
import type { CeriOperationalReport, BaselineComparisonResult, RunManifest } from "./contracts.js";

export class CeriReportGenerator {
  /**
   * Generates a structured operational report from executed evaluation runs and baseline comparisons.
   */
  static generateOperationalReport(
    runs: Array<{ manifest: RunManifest; comparison?: BaselineComparisonResult }>,
    totalAvailableEvaluations: number,
    options?: {
      baselineId?: string;
      limitations?: string[];
    }
  ): CeriOperationalReport {
    let passedRuns = 0;
    let failedRuns = 0;
    let inconclusiveCount = 0;
    let flakyCount = 0;
    let infrastructureFailures = 0;
    let evaluatorDefects = 0;
    let incomparableCount = 0;
    const confirmedRegressions: string[] = [];
    const regressionCandidates: string[] = [];
    const blockers: string[] = [];
    const executedEvaluationIds = new Set<string>();

    let executedRuns = 0;
    let comparedRuns = 0;
    for (const { manifest, comparison } of runs) {
      if (manifest.status === "COMPLETED" || manifest.status === "FAILED") {
        executedRuns++;
        executedEvaluationIds.add(manifest.evaluationId);
        if (comparison?.isEligibleForComparison) comparedRuns++;
      }
      if (manifest.status === "FAILED") failedRuns++;
      else if (manifest.status === "COMPLETED") passedRuns++;

      // Each anomaly metric counts a run at most once, whether the manifest status, the comparison outcome,
      // or both report it (compareRuns echoes the manifest's INCONCLUSIVE/INFRASTRUCTURE_FAILURE/EVALUATOR_DEFECT).
      const outcome = comparison?.outcome;
      const inconclusiveStatuses = ["INTERRUPTED", "INCONCLUSIVE", "NOT_EXECUTED", "CANCELLED"];
      if (inconclusiveStatuses.includes(manifest.status) || outcome === "INCONCLUSIVE" || outcome === "NOT_EXECUTED" || outcome === "CANCELLED") {
        inconclusiveCount++;
      }
      if (manifest.status === "INFRASTRUCTURE_FAILURE" || outcome === "INFRASTRUCTURE_FAILURE") infrastructureFailures++;
      if (manifest.status === "EVALUATOR_DEFECT" || outcome === "EVALUATOR_DEFECT") evaluatorDefects++;
      if (outcome === "FLAKY") flakyCount++;
      if (outcome === "INCOMPARABLE") incomparableCount++;
      if (outcome === "CONFIRMED_REGRESSION") {
        confirmedRegressions.push(comparison!.currentRunId);
        blockers.push(`Confirmed regression in evaluation '${manifest.evaluationId}' (Run ${manifest.runId})`);
      } else if (outcome === "REGRESSION_CANDIDATE") {
        regressionCandidates.push(comparison!.currentRunId);
      }
    }

    const executedEvaluations = executedEvaluationIds.size;
    const rawCoverage =
      executedEvaluations > 0 ? (executedEvaluations / Math.max(1, totalAvailableEvaluations)) * 100 : 0;
    const completenessScore = Number(Math.min(100, Math.max(0, rawCoverage)).toFixed(1));

